{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    # Map each vertex to its group
    group_of = {v: g for v, g in refinement.items()}
    groups = list(set(group_of.values()))
    if len(groups) <= 1:
        return 0
    # Build min weight between each pair of groups
    min_edge = {}
    for u, v, w in edges:
        gu, gv = group_of[u], group_of[v]
        if gu != gv:
            key = (min(gu, gv), max(gu, gv))
            if key not in min_edge or w < min_edge[key]:
                min_edge[key] = w
    # Kruskal's on groups
    parent = {g: g for g in groups}
    rank = {g: 0 for g in groups}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    # Sort edges by weight
    sorted_edges = sorted(min_edge.items(), key=lambda item: item[1])
    total = 0
    cnt = 0
    for (g1, g2), w in sorted_edges:
        if union(g1, g2):
            total += w
            cnt += 1
            if cnt == len(groups) - 1:
                break
    return total
